/// Encode the given value to the given value to a [`String`] using the
/// current [`Encoding`].
///
/// This is the same as [`Encoding::to_string`] but allows for using a
/// configurable [`Context`].
///
/// # Examples
///
/// ```
/// use musli::{Decode, Encode};
/// use musli::json;
/// use musli::alloc::Global;
/// # use musli::json::Error;
///
/// const ENCODING: json::Encoding = json::Encoding::new();
///
/// #[derive(Decode, Encode)]
/// struct Person {
///     name: String,
///     age: u32,
/// }
///
/// let cx = musli::context::new().with_error();
///
/// let mut data = ENCODING.to_string_with(&cx, &Person {
///     name: "Aristotle".to_string(),
///     age: 61,
/// })?;
///
/// let person: Person = ENCODING.from_str_with(&cx, &data[..])?;
/// assert_eq!(person.name, "Aristotle");
/// assert_eq!(person.age, 61);
/// # Ok::<_, Error>(())
/// ```

raw_code:
pub(crate) fn parse_string<'scratch>(
        &mut self,
        validate: bool,
        start: &C::Mark,
        scratch: &'scratch mut Vec<u8, C::Allocator>,
    ) -> Result<StringReference<'de, 'scratch>, C::Error> {
        // Index of the first byte not yet copied into the scratch space.
        let mut open_mark = self.cx.mark();
        let mut open = self.index;

        loop {
            while self.index < self.slice.len() && !ESCAPE[self.slice[self.index] as usize] {
                self.index = self.index.wrapping_add(1);
                self.cx.advance(1);
            }

            if self.index == self.slice.len() {
                return Err(self.cx.message("End of input"));
            }

            match self.slice[self.index] {
                b'"' => {
                    if scratch.is_empty() {
                        // Fast path: return a slice of the raw JSON without any
                        // copying.
                        let borrowed = &self.slice[open..self.index];

                        self.index = self.index.wrapping_add(1);
                        self.cx.advance(1);

                        self.check_utf8(borrowed, start)?;

                        // SAFETY: we've checked each segment to be valid UTF-8.
                        let borrowed = unsafe { core::str::from_utf8_unchecked(borrowed) };
                        return Ok(StringReference::Borrowed(borrowed));
                    } else {
                        let slice = &self.slice[open..self.index];
                        self.check_utf8(slice, start)?;

                        if scratch.extend_from_slice(slice).is_err() {
                            return Err(self.cx.message("Scratch buffer overflow"));
                        }

                        self.index = self.index.wrapping_add(1);
                        self.cx.advance(1);

                        // SAFETY: we've checked each segment to be valid UTF-8.
                        let scratch = unsafe { core::str::from_utf8_unchecked(scratch.as_slice()) };
                        return Ok(StringReference::Scratch(scratch));
                    }
                }
